}
.stat-chip small { display: block; font-size: 8px; letter-spacing: 0.14em; color: var(--muted); }
.stat-chip b { font-family: var(--font-display); font-size: 22px; letter-spacing: 0.04em; }
.icon-button {
  width: 42px; height: 42px;
  border: 1px solid var(--line);
  background: rgba(12, 8, 22, 0.7);
  color: var(--text);
  font-size: 18px;
  cursor: pointer;
  transition: 0.2s;
}
.icon-button:hover { border-color: var(--hot); background: rgba(255, 77, 109, 0.15); }

.menu-main {
  position: relative;
  z-index: 2;
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(300px, 355px) 1fr minmax(320px, 372px);
  gap: 22px;
  padding: 4px 38px 0;
}
.panel {
  align-self: center;
  max-height: 100%;
  padding: 16px;
  border: 1px solid var(--line);
  background: linear-gradient(155deg, rgba(20, 14, 33, 0.88), rgba(10, 7, 18, 0.7));
  backdrop-filter: blur(9px);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  clip-path: polygon(0 0, calc(100% - 15px) 0, 100% 15px, 100% 100%, 15px 100%, 0 calc(100% - 15px));
}
.panel-heading { display: flex; align-items: baseline; gap: 9px; margin-bottom: 12px; }
.panel-heading span { font-family: var(--font-display); color: var(--hot); font-size: 14px; letter-spacing: 0.1em; }
.panel-heading h2 { margin: 0; font-family: var(--font-display); font-size: 23px; letter-spacing: 0.06em; transform: skew(-4deg); }
.map-list { display: flex; flex-direction: column; gap: 7px; }
.map-card {
  position: relative;
  display: grid;
  grid-template-columns: 46px 1fr auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 10px;
  color: var(--text);
  text-align: left;
  border: 1px solid rgba(255,255,255,.09);
  background: rgba(255,255,255,.035);
  cursor: pointer;
  overflow: hidden;
  transition: 0.2s;
}
.map-card::before {
  content: "";
