  inset: 0;
  opacity: 0.18;
  background: linear-gradient(100deg, var(--map-a, #ff9a3c), transparent 70%);
}
.map-card:hover { border-color: rgba(255,255,255,.28); transform: translateX(2px); }
.map-card.active {
  border-color: var(--map-a, var(--orange));
  background: rgba(255,255,255,.08);
  box-shadow: 0 0 25px color-mix(in srgb, var(--map-a, #ff9a3c) 24%, transparent);
}
.map-card .map-icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 46px; height: 42px;
  font-size: 24px;
  background: linear-gradient(140deg, var(--map-a, #ff9a3c), var(--map-b, #7d2f3f));
  border-radius: 4px;
  text-shadow: 0 2px 5px rgba(0,0,0,.55);
}
.map-card .map-copy { position: relative; min-width: 0; }
.map-card b { display: block; font-size: 12.5px; letter-spacing: 0.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.map-card small { display: block; margin-top: 2px; font-size: 9px; letter-spacing: 0.12em; color: var(--muted); }
.map-card .map-check { position: relative; font-size: 12px; color: var(--map-a, var(--orange)); opacity: 0; }
.map-card.active .map-check { opacity: 1; }
.map-detail {
  display: flex;
  gap: 10px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.map-detail .map-art {
  flex: 0 0 58px;
  height: 58px;
  display: grid;
  place-items: center;
  font-size: 28px;
  border: 1px solid var(--line);
  background: radial-gradient(circle at 50% 80%, rgba(255,159,67,.25), transparent 70%);
}
.map-detail b { font-size: 12px; }
.map-detail p { margin: 2px 0 6px; font-size: 10px; line-height: 1.4; color: var(--muted); }
.map-detail span { font-size: 9px; color: var(--orange); font-weight: 800; letter-spacing: 0.05em; }
.season-card {
  margin-top: 12px;
  padding: 10px 11px;
  border: 1px solid rgba(216,255,62,.2);
  background: linear-gradient(120deg, rgba(216,255,62,.08), rgba(168,116,255,.06));
}
.season-top { display: flex; justify-content: space-between; font-size: 9px; letter-spacing: 0.14em; }
.season-top span { color: var(--acid); font-weight: 900; }
.season-top b { color: var(--text); }
.season-bar { height: 4px; margin: 8px 0 7px; background: rgba(255,255,255,.12); }
.season-bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--acid), var(--cyan)); box-shadow: 0 0 10px rgba(216,255,62,.5); }
.season-card p { margin: 0; font-size: 9.5px; line-height: 1.45; color: var(--muted); }
.season-card b { color: var(--acid); }

.center-stage {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
  padding: 12px 0 22px;
}
.stage-top {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border: 1px solid rgba(216,255,62,.3);
  background: rgba(8, 6, 14, 0.5);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: var(--acid);
}
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--acid); box-shadow: 0 0 9px var(--acid); animation: pulse 1.4s infinite; }
@keyframes pulse { 50% { opacity: 0.35; transform: scale(0.7); } }
.stage-name {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
  padding: 13px 25px 14px;
  background: linear-gradient(90deg, transparent, rgba(9, 6, 16, 0.8) 18%, rgba(9,6,16,.8) 82%, transparent);
  text-align: left;
  filter: drop-shadow(0 8px 30px rgba(0,0,0,.7));
}
.stage-name > span { font-size: 42px; filter: drop-shadow(0 3px 10px rgba(0,0,0,.7)); }
.stage-name h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(30px, 3.6vw, 50px);
  letter-spacing: 0.035em;
  line-height: 0.92;
  transform: skew(-5deg);
  text-shadow: 0 0 30px rgba(255,159,67,.2);
}
.stage-name p { margin: 4px 0 0; font-size: 10px; letter-spacing: 0.22em; color: var(--acid); font-weight: 900; text-transform: uppercase; }
.stage-flavor { display: flex; gap: 7px; }
.stage-flavor span { padding: 4px 9px; font-size: 8px; letter-spacing: 0.14em; color: var(--muted); border: 1px solid var(--line); background: rgba(10,7,17,.55); }

.char-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.char-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 8px 3px 7px;
  color: var(--text);
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(255,255,255,.035);
  cursor: pointer;
  transition: 0.18s;
}
.char-card:hover { border-color: rgba(255,255,255,.28); transform: translateY(-2px); }
.char-card.active {
  border-color: var(--char-color, var(--orange));
  background: linear-gradient(180deg, color-mix(in srgb, var(--char-color, #ff9f43) 22%, transparent), rgba(255,255,255,.03));
  box-shadow: 0 0 20px color-mix(in srgb, var(--char-color, #ff9f43) 18%, transparent);
}
.char-card .char-emoji { font-size: 24px; line-height: 1.1; filter: drop-shadow(0 3px 5px rgba(0,0,0,.5)); }
.char-card b { width: 100%; font-size: 8.5px; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.char-card small { font-size: 6.5px; letter-spacing: 0.08em; color: var(--muted); }
.char-card .char-lock { position: absolute; top: 3px; right: 3px; font-size: 7px; color: var(--acid); }
.ability-card { margin-top: 12px; padding: 11px; border: 1px solid var(--line); background: rgba(255,255,255,.025); }
.ability-head { display: flex; align-items: center; gap: 8px; }
.ability-head span { font-size: 8px; letter-spacing: 0.16em; color: var(--cyan); font-weight: 900; }
.ability-head b { font-size: 11px; }
.ability-head.special { margin-top: 10px; padding-top: 9px; border-top: 1px solid var(--line); }
.ability-head.special span { color: var(--hot); }
.ability-card p { margin: 3px 0 0; font-size: 9.5px; line-height: 1.45; color: var(--muted); }
.roster-count { margin-top: 10px; text-align: center; font-size: 8px; letter-spacing: 0.16em; color: var(--muted); }
.roster-count b { color: var(--text); }

.menu-bottom {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 20px;
  padding: 12px 38px 20px;
}
.controls-strip { display: flex; flex-wrap: wrap; gap: 6px 14px; max-width: 440px; font-size: 9px; color: var(--muted); letter-spacing: 0.04em; }
.controls-strip div { display: flex; align-items: center; gap: 5px; }
.play-button {
  position: relative;
  min-width: 265px;
  padding: 13px 46px 12px;
  border: 0;
  color: #1a0710;
  background: linear-gradient(100deg, var(--acid) 0%, #f7ff9e 38%, var(--orange) 100%);
  clip-path: polygon(7% 0, 100% 0, 93% 100%, 0 100%);
  cursor: pointer;
  box-shadow: 0 0 45px rgba(216, 255, 62, 0.25);
  transition: 0.18s;
  overflow: hidden;
}
.play-button > b { position: relative; display: block; font-family: var(--font-display); font-size: 32px; line-height: 0.95; letter-spacing: 0.1em; transform: skew(-6deg); }
.play-button > small { position: relative; display: block; margin-top: 2px; font-size: 8px; font-weight: 900; letter-spacing: 0.26em; }
.play-button:hover { transform: scale(1.035); box-shadow: 0 0 70px rgba(216, 255, 62, 0.4); }
.play-button:active { transform: scale(0.98); }
.play-button.small { min-width: 190px; padding: 10px 28px; }
.play-button.small > b, .play-button.small { font-family: var(--font-display); font-size: 20px; letter-spacing: 0.08em; }
.play-glint {
  position: absolute; top: -50%; bottom: -50%; width: 30px;
  background: rgba(255,255,255,.65);
  transform: rotate(18deg);
  animation: glint 3.2s infinite;
  filter: blur(4px);
}
@keyframes glint { 0%, 65% { left: -20%; opacity: 0; } 72% { opacity: .8; } 100% { left: 120%; opacity: 0; } }
.mythic-strip { justify-self: end; display: flex; gap: 6px; }
.mythic-strip span { display: grid; place-items: center; width: 38px; height: 38px; font-size: 18px; border: 1px solid var(--line); background: rgba(10,7,17,.58); transition: 0.2s; }
.mythic-strip span:hover { border-color: var(--hot); transform: translateY(-2px) rotate(-4deg); }

/* ================= HUD ================= */
#hud { position: fixed; inset: 0; z-index: 15; pointer-events: none; }
.hud-top-left { position: absolute; top: 18px; left: 22px; display: flex; flex-direction: column; gap: 8px; }
.char-badge {
  display: inline-flex; align-items: center; gap: 7px; width: fit-content;
  padding: 6px 12px;
  border-left: 3px solid var(--orange);
  background: linear-gradient(90deg, rgba(10,7,17,.85), transparent);
  font-size: 10px; font-weight: 900; letter-spacing: 0.12em;
}
.char-badge span { font-size: 15px; }
.zone-warning {
  display: none;
  width: fit-content; padding: 6px 12px;
  border: 1px solid rgba(255,77,109,.5);
  background: rgba(255,77,109,.16);
  color: #ff9aac; font-size: 10px; font-weight: 900; letter-spacing: 0.14em;
  animation: warnFlash 0.9s infinite;
}
.zone-warning.visible { display: block; }
@keyframes warnFlash { 50% { opacity: 0.45; } }
.hud-top-center { position: absolute; top: 14px; left: 50%; transform: translateX(-50%); text-align: center; }
.match-bar {
  display: flex; align-items: center; justify-content: center; gap: 16px;
  min-width: 320px; padding: 6px 20px;
  border: 1px solid var(--line);
  border-top: 2px solid var(--hot);
  background: linear-gradient(180deg, rgba(10,7,17,.86), rgba(10,7,17,.55));
  clip-path: polygon(3% 0, 97% 0, 100% 100%, 0 100%);
}
.match-stat { min-width: 62px; }
.match-stat small { display: block; font-size: 7px; letter-spacing: 0.22em; color: var(--muted); }
.match-stat b { font-family: var(--font-display); font-size: 25px; letter-spacing: 0.04em; line-height: 1; }
.match-divider { width: 1px; height: 24px; background: var(--line); }
.compass { margin-top: 4px; font-size: 9px; font-weight: 900; letter-spacing: 0.24em; color: rgba(255,255,255,.78); text-shadow: 0 1px 4px #000; }
.zone-bar { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 5px; font-size: 8px; font-weight: 900; letter-spacing: 0.12em; color: var(--muted); }
.zone-bar i { width: 40px; height: 1px; background: linear-gradient(90deg, transparent, var(--orange), transparent); }
.zone-bar b { color: var(--orange); }
.hud-top-right { position: absolute; top: 16px; right: 20px; display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.minimap-wrap { position: relative; padding: 5px; border: 1px solid rgba(255,255,255,.2); background: rgba(6,4,10,.72); box-shadow: 0 10px 35px rgba(0,0,0,.45); }
#minimap { display: block; width: 172px; height: 172px; border: 1px solid rgba(255,255,255,.1); }
.minimap-label { position: absolute; bottom: -17px; right: 0; font-size: 7px; letter-spacing: 0.22em; color: var(--muted); }
.killfeed { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; margin-top: 10px; max-width: 290px; }
.feed-entry { padding: 3px 8px; font-size: 9px; letter-spacing: 0.02em; background: rgba(7,4,12,.62); border-right: 2px solid var(--line); animation: feedIn 0.2s ease; transition: opacity .7s; }
.feed-entry.out { opacity: 0; }
.feed-entry b { color: #ffb0b0; }
.feed-entry b.you { color: var(--acid); }
.feed-entry span { color: var(--muted); }
@keyframes feedIn { from { transform: translateX(20px); opacity: 0; } }

.event-banner {
  position: absolute; top: 19%; left: 50%;
  transform: translate(-50%, -10px) skew(-4deg);
  font-family: var(--font-display);
  font-size: clamp(22px, 3.1vw, 46px);
  letter-spacing: 0.045em;
  color: #fff;
  text-shadow: 0 0 20px rgba(255,77,109,.9), 0 0 60px rgba(255,77,109,.55), 3px 3px 0 #4c0c1b;
  opacity: 0; transition: 0.25s;
  white-space: nowrap;
}
.event-banner.show { opacity: 1; transform: translate(-50%, 0) skew(-4deg); }
.event-sub {
  position: absolute; top: calc(19% + 46px); left: 50%;
  transform: translateX(-50%);
  font-size: 10px; font-weight: 900; letter-spacing: 0.2em;
  color: var(--acid); text-shadow: 0 1px 5px #000;
  opacity: 0; transition: 0.25s;
}
.event-sub.show { opacity: 1; }

.chat-log { position: absolute; left: 22px; bottom: 148px; display: flex; flex-direction: column; gap: 3px; width: min(410px, 42vw); }
.chat-entry { padding: 3px 8px; font-size: 9.5px; background: linear-gradient(90deg, rgba(7,4,12,.62), transparent); transition: opacity .8s; }
.chat-entry b { color: var(--cyan); margin-right: 6px; }
.chat-entry span { color: rgba(255,255,255,.78); }
.chat-entry.system { color: var(--acid); background: linear-gradient(90deg, rgba(216,255,62,.09), transparent); }
.chat-entry.system b { color: var(--acid); }
.chat-entry.out { opacity: 0; }

.hud-bottom-left { position: absolute; left: 22px; bottom: 22px; display: flex; flex-direction: column; gap: 8px; width: min(380px, 34vw); }
.vitals { padding: 9px 12px; background: linear-gradient(90deg, rgba(9,6,15,.82), rgba(9,6,15,.25)); border-left: 3px solid var(--hot); }
.vital-row { display: flex; align-items: center; gap: 8px; }
.vital-row + .vital-row { margin-top: 5px; }
.vital-icon { width: 14px; font-size: 11px; }
.vital-track { position: relative; flex: 1; height: 10px; background: rgba(255,255,255,.11); overflow: hidden; }
.vital-track i { display: block; height: 100%; width: 100%; transition: width .18s; }
.vital-row.hp .vital-track i { background: linear-gradient(90deg, #ff375b, #ff8a5c); box-shadow: 0 0 13px rgba(255,55,91,.6); }
.vital-row.hp .vital-track i.low { background: #ff203f; animation: lowHp .7s infinite; }
@keyframes lowHp { 50% { opacity: 0.55; } }
.vital-row.armor .vital-track { height: 5px; }
.vital-row.armor .vital-track i { background: linear-gradient(90deg, #3fa9ff, #66e2ff); box-shadow: 0 0 10px rgba(63,169,255,.5); }
.vital-row b { min-width: 38px; text-align: right; font-size: 12px; font-weight: 900; font-variant-numeric: tabular-nums; }
.special-card { display: flex; align-items: center; gap: 9px; padding: 7px 11px; background: rgba(9,6,15,.7); border: 1px solid var(--line); width: fit-content; }
.special-key { display: grid; place-items: center; width: 30px; height: 30px; font-family: var(--font-display); font-size: 18px; color: var(--acid); border: 1px solid rgba(216,255,62,.35); background: rgba(216,255,62,.09); }
.special-info b { display: block; font-size: 9px; letter-spacing: 0.08em; }
.special-track { width: 110px; height: 3px; margin-top: 4px; background: rgba(255,255,255,.14); }
.special-track i { display: block; height: 100%; width: 100%; background: var(--acid); box-shadow: 0 0 8px var(--acid); }
.special-track i.ready { animation: readyGlow 1.2s infinite; }
@keyframes readyGlow { 50% { opacity: .5; } }
.special-card > span { font-size: 8px; font-weight: 900; letter-spacing: .12em; color: var(--acid); }

.crosshair { position: absolute; top: 50%; left: 50%; width: 34px; height: 34px; transform: translate(-50%, -50%); opacity: .95; }
.crosshair i { position: absolute; background: rgba(255,255,255,.95); box-shadow: 0 0 4px rgba(0,0,0,.8); }
.crosshair i:nth-child(1) { width: 2px; height: 8px; top: 0; left: 16px; }
.crosshair i:nth-child(2) { width: 2px; height: 8px; bottom: 0; left: 16px; }
.crosshair i:nth-child(3) { width: 8px; height: 2px; left: 0; top: 16px; }
.crosshair i:nth-child(4) { width: 8px; height: 2px; right: 0; top: 16px; }
.crosshair span { position: absolute; left: 16px; top: 16px; width: 2px; height: 2px; border-radius: 50%; background: var(--acid); box-shadow: 0 0 5px var(--acid); }
.crosshair.aiming i { opacity: .5; }
.hitmarker { position: absolute; top: 50%; left: 50%; width: 38px; height: 38px; transform: translate(-50%,-50%) rotate(45deg) scale(1.2); opacity: 0; }
.hitmarker i { position: absolute; width: 2px; height: 9px; background: #fff; }
.hitmarker i:nth-child(1) { left: 8px; top: 8px; }
.hitmarker i:nth-child(2) { right: 8px; top: 8px; }
.hitmarker i:nth-child(3) { left: 8px; bottom: 8px; }
.hitmarker i:nth-child(4) { right: 8px; bottom: 8px; }
.hitmarker.show { animation: hit 0.16s ease; }
.hitmarker.crit i { background: #ff5a5a; }
@keyframes hit { 0% { opacity: 1; } 100% { opacity: 0; } }

.hud-bottom-center { position: absolute; left: 50%; bottom: 18px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 10px; }
.weapon-panel {
  display: flex; align-items: center; gap: 13px;
  min-width: 380px; padding: 9px 16px;
  border: 1px solid var(--line); border-bottom: 2px solid var(--orange);
  background: linear-gradient(180deg, rgba(14,9,24,.5), rgba(9,6,15,.88));
  clip-path: polygon(2% 0, 98% 0, 100% 100%, 0 100%);
}
.weapon-icon { font-size: 28px; filter: drop-shadow(0 2px 5px #000); }
.weapon-meta { flex: 1; }
.weapon-meta span { display: block; font-size: 7px; letter-spacing: 0.2em; color: var(--orange); font-weight: 900; }
.weapon-meta b { display: block; font-size: 14px; font-weight: 900; letter-spacing: 0.03em; }
.ammo-track { width: 100%; height: 3px; margin-top: 5px; background: rgba(255,255,255,.14); }
.ammo-track i { display: block; width: 100%; height: 100%; background: var(--orange); box-shadow: 0 0 8px rgba(255,159,67,.6); transition: width .15s; }
.ammo-count { display: flex; align-items: baseline; gap: 4px; font-variant-numeric: tabular-nums; }
.ammo-count b { font-family: var(--font-display); font-size: 31px; line-height: 1; }
.ammo-count span { color: var(--muted); font-size: 13px; }
.ammo-count small { color: var(--muted); font-size: 14px; }
.interact-prompt {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 14px; border: 1px solid rgba(216,255,62,.4);
  background: rgba(9,7,16,.86);
  animation: promptBob 1.6s infinite;
}
@keyframes promptBob { 50% { transform: translateY(-3px); } }
.interact-prompt kbd { color: var(--acid); border-color: rgba(216,255,62,.5); }
.interact-prompt b { display: block; font-size: 11px; }
.interact-prompt small { display: block; margin-top: 1px; color: var(--muted); font-size: 8px; letter-spacing: .08em; }

.hud-bottom-right { position: absolute; right: 22px; bottom: 22px; display: flex; flex-direction: column; align-items: flex-end; gap: 9px; }
.weapon-slots { display: flex; gap: 5px; }
.weapon-slot {
  position: relative; width: 92px; padding: 6px 7px 5px;
