.damage-flash { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(circle, transparent 38%, rgba(255,30,55,.4) 100%); box-shadow: inset 0 0 120px rgba(255,20,50,.65); }
