async () => {
  const g = window.__memeShoter()
  const c = await import('/src/combat.js')
  g.toMenu(); g.setMap('volcano'); g.startMatch()
  await new Promise(r => setTimeout(r, 600))
  const out = { start: { mode: g.mode, bots: g.bots.length, hp: g.player.hp, inv: g.inventory.map(e => e && e.id), alive: g.alive } }
  const b = g.bots.find(x => x.alive)
  const beforeKills = g.kills
  c.damageBot(g, b, 5000, { player: true, crit: true })
  out.kill = { botAlive: b.alive, kills: g.kills, delta: g.kills - beforeKills, lootCount: g.loot.length }
  // loot pickup
  const loot = c.spawnLoot(g, g.player.pos.x + 1.2, g.player.pos.z, 'ak')
  g.nearLoot = loot
  c.interact(g)
  out.loot = { inv: g.inventory.map(e => e && e.id), slot: g.slot, nearLoot: !!g.nearLoot }
  // fire + reload
  const entry = g.inventory[g.slot]
  const magBefore = entry.mag
  g.fireCooldown = 0
  c.tryFire(g)
  const magAfter = entry.mag
  c.startReload(g)
  out.reload = { magBefore, magAfter, reloading: g.reloading }
  // special
  g.specialCooldown = 0
  c.useSpecial(g)
  out.special = { cooldown: Math.round(g.specialCooldown * 10) / 10 }
  // zone
  out.zone = g.zone && { r: Math.round(g.zone.r), timer: Math.round(g.zone.timer), label: g.zone.label }
  // defeat
  c.damagePlayer(g, 99999, { name: 'Test Bot' }, {})
  await new Promise(r => setTimeout(r, 400))
  out.defeat = { mode: g.mode, alive: g.alive, endShown: g.endShown, endHidden: document.getElementById('end-screen').classList.contains('hidden'), title: document.getElementById('end-title').textContent }
  // replay
