export function damageBot(game, bot, amount, opts = {}) {
  if (!bot || !bot.alive) return
  bot.hp -= amount
  if (opts.player) {
    game.damageDealt += amount
    game.floatText(V(bot.pos.x, bot.pos.y + 1.75, bot.pos.z), `${Math.round(amount)}${opts.crit ? ' CRIT' : ''}`, opts.crit)
