}

export function damagePlayer(game, amount, source, opts = {}) {
  if (!game.alive) return
  const p = game.player
  if (game.character.id === 'pana' && opts.explosive) amount *= 0.8
  let dmg = amount
  if (p.armor > 0) {
    const absorbed = Math.min(p.armor, dmg * 0.55)
    p.armor -= absorbed
    dmg -= absorbed
  }
  p.hp -= dmg
