export function spawnLoot(game, x, z, weaponId = null) {
  if (game.loot.length > 30) {
    const old = game.loot.find((l) => !l.taken)
    if (old) { game.scene.remove(old.group); old.taken = true; game.loot.splice(game.loot.indexOf(old), 1) }
  }
