async () => {
  const g = window.__memeShoter()
  const c = await import('/src/combat.js')
  g.toMenu(); g.setMap('volcano'); g.startMatch()
  const test = (yaw, key) => {
    g.player.pos.set(48, 0, 44)
    g.player.yaw = yaw
    g.player.pitch = 0
    g.keys = { [key]: true }
    g.lastActivity = 0
    c.updateMatch(g, 0.05)
    g.keys = {}
    const dx = g.player.pos.x - 48
    const dz = g.player.pos.z - 44
    const fx = -Math.sin(yaw)
    const fz = -Math.cos(yaw)
    const rx = Math.cos(yaw)
    const rz = -Math.sin(yaw)
    const expected = key === 'KeyW' ? [fx, fz] : key === 'KeyS' ? [-fx, -fz] : key === 'KeyA' ? [-rx, -rz] : [rx, rz]
    const dot = dx * expected[0] + dz * expected[1]
    return { yaw: Math.round(yaw * 100) / 100, key, dx: Math.round(dx * 1000) / 1000, dz: Math.round(dz * 1000) / 1000, dot: Math.round(dot * 10000) / 10000 }
  }
  return {
    w0: test(0, 'KeyW'), w45: test(Math.PI / 4, 'KeyW'), w90: test(Math.PI / 2, 'KeyW'), wm90: test(-Math.PI / 2, 'KeyW'),
    a45: test(Math.PI / 4, 'KeyA'), d45: test(Math.PI / 4, 'KeyD'), s135: test(3 * Math.PI / 4, 'KeyS')
  }
}
EOF
